    for (const s of SITES) { const l = worldToSite(s, x, z); if (Math.abs(l[0]) < s.w / 2 + pad + (s.porch || 0) + 0.5 && Math.abs(l[1]) < s.d / 2 + pad + 0.5) return false; }
