    const hx = hr.x + 1.4; for (let k = 0; k < 4 + (R() * 3 | 0); k++) { const z = hr.z + (k - 2) * 0.55 + R.s() * 0.1; if (Math.abs(z) < Z1 - 0.4) at(c.int, hx + R.s() * 0.25, H - 0.26, z, 0, () => herbs(c.int, R)); }
