        const x = w[0] + w[3] * dist + Math.sin(time * 0.3 + ph * 3) * 0.25 + (k - 3) * w[5] * 0.28 * (-w[4]), z = w[2] + w[4] * dist + Math.cos(time * 0.27 + ph) * 0.25 + (k - 3) * w[5] * 0.28 * w[3], y = w[1] - 0.3 + Math.sin(ph * 2.1) * 0.5 - f * 0.5 + Math.sin(time * 0.4 + ph) * 0.12;
