// a level: k (-1, 0, 1), y = floor height above the entrance floor, H = clear height to the ceiling slab
function pLevel(P, k, y, H, o) { P.lv[k] = Object.assign({ k, y, H, rooms: [], items: [] }, o || {}); return P.lv[k]; }
