        const WIN = room.winKinds || WIN0, kind = WIN[Math.abs(Math.round(wl.c * 3 + p * 7)) % WIN.length], o = { type: 'win', pos: p, hw: 0.8, kind, glass: room.glass ? room.glass[P.windows.length % room.glass.length] : null };
