const WARE_W = { rope: 0.28, lantern: 0.14, flask: 0.2, tall: 0.11, jar: 0.2, demijohn: 0.28, bolt: 0.17, folded: 0.3, sack: 0.3, box: 0.27, candles: 0.2, spools: 0.34, tools: 0.45, cheese: 0.26, loaf: 0.3, bowl: 0.2, pot: 0.25, ham: 0.24 };
