    const ang = Math.atan2(b[1] - a[1], b[0] - a[0]), mx = (a[0] + b[0]) / 2, mz = (a[1] + b[1]) / 2, l = L / 2 + 0.04, m = bucket(mx, mz), ramp = i < first || i >= last;
