      const k = e.always ? 1 : lit;
      put(e.p[0], e.p[1], e.p[2], 0.05, 1, 1, 1, 0.9 * k, 0, 2, 1.7, e.seed); put(e.p[0], e.p[1] + 0.01, e.p[2], 0.2, 1.0, 0.6, 0.22, 0.5 * k, 0, 0, 1, e.seed);
