        a.pos[1] += (World.groundAt(a.pos[0], a.pos[2], a.pos[1] + 0.6) - a.pos[1]) * Math.min(1, step * 6);
        a.yaw += angDiff(Math.atan2(dx, -dz), a.yaw) * Math.min(1, step * 8); a.anim = 'walk';
