  $('pauseNote').textContent = why === 'hidden' ? 'Your progress is saved while you are away.' : why === 'turn' ? 'Turn your phone sideways to carry on.' : 'Your progress is saved.';
  if (!UI.menu) $('pause').hidden = false;
