    S.nb(o, t, { f: 1600 * j, f2: 700, q: 0.7, a: 0.01, d: 0.24, v: 0.5 * v }); S.nb(o, t, { type: 'lowpass', f: 260, d: 0.12, v: 0.6 * v });
