  def('pickup.generic', 'ui', 1, 0.5, (S, c, o, t, v) => { S.nb(o, t, { f: 2400, q: 0.4, a: 0.025, d: 0.15, v: 0.25 * v, hp: 1000 }); S.modal(o, t + 0.02, 600, [[1, 0.4, 0.07], [2.3, 0.2, 0.04]], 0.4 * v); });
