  const CELL = 10, HALF = 180, NG = HALF * 2 / CELL;
  const SPACE = id => /cellar|crypt|dungeon|cave|undercroft|tomb|mine|tower|vault/.test(id) ? 'cave' : /chapel|inn|hall|barn|temple|church/.test(id) ? 'hall' : 'room';
