  const hc = (i, j) => { let h = 0; for (const [a, b] of [[0, 0], [-1, 0], [0, -1], [-1, -1]]) { const c = get(i + a, j + b); if (c) h = Math.max(h, c.reg.h + flat(c.reg, i, j)); } return h; };
