    m.quad(W(i, fl(i, j), j), W(i, fl(i, j + 1), j + 1), W(i + 1, fl(i + 1, j + 1), j + 1), W(i + 1, fl(i + 1, j), j), i / T, j / T, (i + 1) / T, (j + 1) / T);
