    m.quad(P(i, j + 1, 3, ceilY(i, j + 1)), P(i, j, 3, ceilY(i, j)), P(i + 1, j, 3, ceilY(i + 1, j)), P(i + 1, j + 1, 3, ceilY(i + 1, j + 1)), i / T, j / T, (i + 1) / T, (j + 1) / T);
