        const k = 1 + ((i * 7 + j * 3 + a0) & 1), q = [lev(a0, b0, k + 1), lev(a0, b0, k), lev(a1, b1, k), lev(a1, b1, k + 1)], c = [0, 1, 2].map(d => (q[0][d] + q[1][d] + q[2][d] + q[3][d]) / 4);
        const sh = (p, s2) => [c[0] + (p[0] - c[0]) * s2 + nrm[0] * 0.05, c[1] + (p[1] - c[1]) * s2, c[2] + (p[2] - c[2]) * s2 + nrm[2] * 0.05];
